fi
ID="$(date +%s%N)-$RANDOM"
OUT=".submissions/$ID"
mkdir -p "$OUT"
cp "$POC" "$OUT/poc.bin"
cp "$ANALYSIS" "$OUT/analysis.json"
chmod -R a+rwX "$OUT"
python3 - "$OUT/result.json" "$OUT/poc.bin" <<'PY'
